input.content:
try {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const q = sel => [...document.querySelectorAll(sel)];
  const text = () => document.body.innerText;
  const log = [];
  const visible = el => { const r = el.getBoundingClientRect(); return r.width > 1 && r.height > 1; };

  // ---- cursor overlay ----
  let cur = document.getElementById('__demo_cursor');
  if (!cur) {
    cur = document.createElement('div');
    cur.id = '__demo_cursor';
    cur.style.cssText = 'position:fixed;z-index:2147483647;pointer-events:none;left:30px;top:30px;width:26px;height:26px;';
    cur.innerHTML = '<svg viewBox="0 0 24 24" style="filter:drop-shadow(0 0 2px rgba(0,0,0,.7))"><path d="M4 2 L18.5 11.5 L11.5 12.5 L15 20.5 L12.4 21.7 L9 13.7 L4 17.5 Z" fill="#ffffff" stroke="#111111" stroke-width="1.4"/></svg>';
    document.body.appendChild(cur);
  }
  cur.style.display = 'block';
  let rip = document.getElementById('__demo_ripple');
  if (!rip) {
    rip = document.createElement('div');
    rip.id = '__demo_ripple';
    rip.style.cssText = 'position:fixed;z-index:2147483646;pointer-events:none;border:2px solid rgba(255,90,90,.95);border-radius:50%;width:8px;height:8px;transform:translate(-50%,-50%);opacity:0;transition:all .22s ease-out;left:-100px;top:-100px;';
    document.body.appendChild(rip);
  }
  async function ripple(x, y) {
    rip.style.transition = 'none';
    rip.style.left = x + 'px'; rip.style.top = y + 'px';
    rip.style.width = '8px'; rip.style.height = '8px'; rip.style.opacity = '1';
    void rip.offsetWidth;
    rip.style.transition = 'all .25s ease-out';
    rip.style.width = '56px'; rip.style.height = '56px'; rip.style.opacity = '0';
    await sleep(180);
  }
  async function glide(x, y, ms) {
    ms = ms || 500;
    const steps = Math.max(5, Math.round(ms / 90));
    const x0 = parseFloat(cur.style.left) || 30;
    const y0 = parseFloat(cur.style.top) || 30;
    for (let i = 1; i <= steps; i++) {
      cur.style.left = (x0 + (x - x0) * i / steps) + 'px';
      cur.style.top = (y0 + (y - y0) * i / steps) + 'px';
      await sleep(90);
    }
  }
  const center = el => { const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; };
  const btn = sub => q('button').find(b => b.innerText.includes(sub));
  async function clickBtn(sub) { const b = btn(sub); if (!b) throw new Error('no button ' + sub); const c = center(b); await glide(c.x, c.y); await ripple(c.x, c.y); b.click(); }
  async function waitText(t, timeout) { timeout = timeout || 40000; const s = Date.now(); while (!text().includes(t)) { if (Date.now() - s > timeout) throw new Error('timeout waiting text: ' + t); await sleep(200); } }
  async function waitRunning(timeout) { timeout = timeout || 60000; const s = Date.now(); while (text().includes('RUNNING')) { if (Date.now() - s > timeout) throw new Error('timeout waiting for rerun to finish'); await sleep(250); } }
  const radioInput = label => { const l = q('label').find(x => x.innerText.trim() === label && x.querySelector('input[type=radio]') && visible(x)); return l && l.querySelector('input[type=radio]'); };

  async function dragVisible(label, delta) {
    const block = q('[data-testid=stSlider]').find(b => b.innerText.startsWith(label) && visible(b));
    if (!block) return { miss: label };
    let thumb = block.querySelector('[role=slider]');
    const min = +thumb.getAttribute('aria-valuemin');
    const max = +thumb.getAttribute('aria-valuemax');
    const v0 = +thumb.getAttribute('aria-valuenow');
    const target = Math.max(min, Math.min(max, v0 + delta));
    const r = block.getBoundingClientRect();
    const y = center(thumb).y;
    const x0 = center(thumb).x;
    const x1 = x0 + (target - v0) / (max - min) * (r.width * 0.92);
    await glide(x0, y, 350);
    await ripple(x0, y);
    const pd = (type, tgt, x, btns) => {
      tgt.dispatchEvent(new PointerEvent(type, { bubbles: true, cancelable: true, view: window, pointerId: 1, pointerType: 'mouse', isPrimary: true, clientX: x, clientY: y, buttons: btns, button: 0 }));
      const mt = type === 'pointerdown' ? 'mousedown' : type === 'pointermove' ? 'mousemove' : 'mouseup';
      tgt.dispatchEvent(new MouseEvent(mt, { bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, buttons: btns, button: 0 }));
    };
    pd('pointerdown', thumb, x0, 1);
    for (let i = 1; i <= 6; i++) { pd('pointermove', thumb, x0 + (x1 - x0) * i / 6, 1); await sleep(60); }
    pd('pointerup', thumb, x1, 0);
    await sleep(500);
    let v1 = +block.querySelector('[role=slider]').getAttribute('aria-valuenow');
    let kb = false;
    if (v1 !== target) {
      const block2 = q('[data-testid=stSlider]').find(b => b.innerText.startsWith(label) && visible(b));
      const t2 = block2.querySelector('[role=slider]');
      t2.focus();
      const n = target - (+t2.getAttribute('aria-valuenow'));
      const key = n > 0 ? 'ArrowRight' : 'ArrowLeft';
      for (let i = 0; i < Math.min(Math.abs(n), 220); i++) {
        t2.dispatchEvent(new KeyboardEvent('keydown', { key: key, code: key, keyCode: key === 'ArrowRight' ? 39 : 37, which: key === 'ArrowRight' ? 39 : 37, bubbles: true }));
        await sleep(50);
      }
      await sleep(500);
      kb = true;
      v1 = +q('[data-testid=stSlider]').find(b => b.innerText.startsWith(label) && visible(b)).querySelector('[role=slider]').getAttribute('aria-valuenow');
    }
    await waitRunning();
    await sleep(400);
    return { label: label, v0: v0, v1: v1, target: target, kb: kb };
  }

  // ================= phase 1 =================
  const h = document.querySelector('header[data-testid=stHeader]');
  if (h) h.style.display = 'none';

  await waitText('Load Demo Phantom', 60000);
  await clickBtn('Load Demo Phantom');
  await waitText('Demo Mode', 60000);
  await waitRunning(120000);
  if (text().includes('not connected to a server')) throw new Error('media server connection error after demo load');
  await sleep(700);

  // 2D view
  const r2d = radioInput('2D');
  { const c = center(r2d.closest('label')); await glide(c.x, c.y); await ripple(c.x, c.y); }
  r2d.click();
  await waitRunning(60000);
  await sleep(700);

  // expand Slice Options if its sliders are not visible yet
  if (!q('[data-testid=stSlider]').some(b => b.innerText.startsWith('Axial Slice') && visible(b))) {
    await clickBtn('Slice Options');
    await waitRunning(60000);
    await sleep(600);
  }
  // scrub a slice slider that is actually visible (windowing sliders may live in 3D options)
  let win = await dragVisible('Axial Slice', 18);
  if (win.miss) win = await dragVisible('Coronal Slice', 18);
  if (win.miss) win = await dragVisible('Center (HU)', 260);
  log.push({ slice: win });
  await sleep(800);

  // 3D view
  const r3d = radioInput('3D');
  { const c = center(r3d.closest('label')); await glide(c.x, c.y); await ripple(c.x, c.y); }
  r3d.click();
  await waitRunning(60000);
  await sleep(900);

  // move cursor to the Source Trajectory legend toggle and report its coords for trusted CDP clicks
  const gd = [...document.querySelectorAll('.js-plotly-plot')].find(p => [...p.querySelectorAll('text.legendtext')].some(t => t.textContent.trim() === 'Source Trajectory' && visible(t)));
  if (!gd) throw new Error('no 3D plot with Source Trajectory legend');
  const g = [...gd.querySelectorAll('g.traces')].find(x => x.querySelector('text.legendtext').textContent.trim() === 'Source Trajectory');
  const tr = g.querySelector('.legendtoggle').getBoundingClientRect();
  const tx = tr.left + tr.width / 2, ty = tr.top + tr.height / 2;
  await glide(tx, ty, 500);

  return { ok: true, log: log, toggleX: tx, toggleY: ty };
} catch (e) {
  return { ok: false, error: String(e && e.message || e) };
}

