    const max = +thumb.getAttribute('aria-valuemax');
    const v0 = +thumb.getAttribute('aria-valuenow');
    const target = Math.max(min, Math.min(max, v0 + delta));
    const r = block.getBoundingClientRect();
    const y = center(thumb).y;
    const x0 = center(thumb).x;
    const x1 = x0 + (target - v0) / (max - min) * (r.width * 0.92);
    await glide(x0, y, 350);
    await ripple(x0, y);
    const pd = (type, tgt, x, btns) => {
      tgt.dispatchEvent(new PointerEvent(type, { bubbles: true, cancelable: true, view: window, pointerId: 1, pointerType: 'mouse', isPrimary: true, clientX: x, clientY: y, buttons: btns, button: 0 }));
      const mt = type === 'pointerdown' ? 'mousedown' : type === 'pointermove' ? 'mousemove' : 'mouseup';
      tgt.dispatchEvent(new MouseEvent(mt, { bubbles: true, cancelable: true, view: window, clientX: x, clientY: y, buttons: btns, button: 0 }));
    };
    pd('pointerdown', thumb, x0, 1);
    for (let i = 1; i <= 6; i++) { pd('pointermove', thumb, x0 + (x1 - x0) * i / 6, 1); await sleep(60); }
    pd('pointerup', thumb, x1, 0);
    await sleep(500);
    let v1 = +block.querySelector('[role=slider]').getAttribute('aria-valuenow');
    let kb = false;
    if (v1 !== target) {
      const block2 = q('[data-testid=stSlider]').find(b => b.innerText.startsWith(label) && visible(b));
      const t2 = block2.querySelector('[role=slider]');
      t2.focus();
      const n = target - (+t2.getAttribute('aria-valuenow'));
      const key = n > 0 ? 'ArrowRight' : 'ArrowLeft';
      for (let i = 0; i < Math.min(Math.abs(n), 220); i++) {
        t2.dispatchEvent(new KeyboardEvent('keydown', { key: key, code: key, keyCode: key === 'ArrowRight' ? 39 : 37, which: key === 'ArrowRight' ? 39 : 37, bubbles: true }));
        await sleep(50);
      }
      await sleep(500);
      kb = true;
      v1 = +q('[data-testid=stSlider]').find(b => b.innerText.startsWith(label) && visible(b)).querySelector('[role=slider]').getAttribute('aria-valuenow');
    }
    await waitRunning();
    await sleep(400);
    return { label: label, v0: v0, v1: v1, target: target, kb: kb };
  }

  // ================= phase 2 =================
  await clickBtn('Sinogram Inspection');
  await waitRunning(60000);
  await sleep(600);

  let fp = { ran: false };
  if (!text().includes('Simulated projection')) {
    await clickBtn('Run Forward Projection');
    fp = { ran: true };
    await waitRunning(240000);
    await waitText('Simulated projection', 60000);
    await sleep(600);
  }

  const pi = await dragVisible('Projection index', 28);
  log.push({ projIndex: pi });
  await sleep(900);

  cur.style.display = 'none';
  return { ok: true, log: log, fp: fp };
} catch (e) {
  return { ok: false, error: String(e && e.message || e) };
}

param(
    [int]$Port = 9223,
    [string]$OutDir = "C:\Users\laura\AppData\Local\Temp\opencode\ctvideo\frames_short",
    [string]$PhaseA = "C:\Users\laura\AppData\Local\Temp\opencode\ctvideo\choreo_phase1.js",
    [string]$PhaseB = "C:\Users\laura\AppData\Local\Temp\opencode\ctvideo\choreo_phase2.js",
    [double]$MinFrameGap = 0.12
)
$ErrorActionPreference = 'Stop'

if (Test-Path $OutDir) { Remove-Item "$OutDir\*" -Force -ErrorAction SilentlyContinue } else { New-Item -ItemType Directory -Force $OutDir | Out-Null }
$frames = New-Object System.Collections.Generic.List[object]

$list = Invoke-RestMethod "http://localhost:$Port/json/list"
$target = $list | Where-Object { $_.type -eq 'page' -and $_.url -like '*localhost:8501*' } | Select-Object -First 1
if (-not $target) { throw "no page target on port $Port" }

$ws = [System.Net.WebSockets.ClientWebSocket]::new()
$cts = [System.Threading.CancellationTokenSource]::new()
$ws.ConnectAsync([Uri]$target.webSocketDebuggerUrl, $cts.Token).Wait()

$script:msgId = 0
$script:pending = @{}
$script:responses = @{}
$script:lastSavedTs = 0
$script:frameNo = 0
$script:overflow = $false

function Send-Cdp {
    param($method, $params)
    $script:msgId++
    $obj = @{ id = $script:msgId; method = $method }
    if ($params) { $obj.params = $params }
    $json = ConvertTo-Json $obj -Depth 12 -Compress
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
    $ws.SendAsync([ArraySegment[byte]]::new($bytes), 'Text', $true, $cts.Token).Wait()
    $script:pending[$script:msgId] = $method
    return $script:msgId
}

function Read-One {
    $buf = New-Object byte[] (1MB)
    $ms = New-Object System.IO.MemoryStream
    do {
        $r = $ws.ReceiveAsync([ArraySegment[byte]]::new($buf), $cts.Token)
        $r.Wait()
        $res = $r.Result
        if ($res.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close) { throw 'ws closed' }
        $ms.Write($buf, 0, $res.Count)
    } while (-not $res.EndOfMessage)
    $txt = [System.Text.Encoding]::UTF8.GetString($ms.ToArray())
    $ms.Dispose()
    return ($txt | ConvertFrom-Json)
}

function Handle-Message {
    param($msg)
    if ($msg.method -eq 'Page.screencastFrame') {
        $p = $msg.params
        $ts = [double]$p.metadata.timestamp
        $dur = 0.0
        if ($script:lastSavedTs -gt 0) { $dur = $ts - $script:lastSavedTs }
        if ($script:lastSavedTs -eq 0 -or $dur -ge $MinFrameGap) {
            $script:frameNo++
            $file = "frame_{0:d4}.jpg" -f $script:frameNo
            [IO.File]::WriteAllBytes((Join-Path $OutDir $file), [Convert]::FromBase64String($p.data))
            if ($script:lastSavedTs -gt 0) { $frames.Add(@{ file = $file; dur = $dur }) }
            $script:lastSavedTs = $ts
            if ($script:frameNo -gt 450) { $script:overflow = $true }
        }
        Send-Cdp 'Page.screencastFrameAck' @{ sessionId = $p.sessionId } | Out-Null
    }
    elseif ($msg.id -and $script:pending.ContainsKey([int]$msg.id)) {
        $script:responses[[int]$msg.id] = $msg
        $script:pending.Remove([int]$msg.id)
    }
}

function Wait-Response {
    param($id)
    while (-not $script:responses.ContainsKey($id)) {
        if ($script:overflow) { break }
        Handle-Message (Read-One)
    }
    if ($script:responses.ContainsKey($id)) { $r = $script:responses[$id]; $script:responses.Remove($id); return $r }
    return $null
}

function Pump {
    # guaranteed traffic so queued screencast frames get processed
    $id = Send-Cdp 'Runtime.evaluate' @{ expression = '1+1'; returnByValue = $true }
    Wait-Response $id | Out-Null
}

function Trusted-Click {
    param([double]$x, [double]$y)
    foreach ($type in @('mouseMoved', 'mousePressed', 'mouseReleased')) {
        $p = @{ type = $type; x = $x; y = $y; button = 'left'; buttons = 1; clickCount = 1 }
        if ($type -eq 'mouseReleased') { $p.buttons = 0 }
        $id = Send-Cdp 'Input.dispatchMouseEvent' $p
        Wait-Response $id | Out-Null
    }
}

Send-Cdp 'Page.enable' @{} | Out-Null
Send-Cdp 'Page.startScreencast' @{ format = 'jpeg'; quality = 60; maxWidth = 1280; maxHeight = 720; everyNthFrame = 1 } | Out-Null
Start-Sleep -Milliseconds 300

# ---------- phase A ----------
$jsA = '(async () => {' + (Get-Content $PhaseA -Raw) + '})()'
$idA = Send-Cdp 'Runtime.evaluate' @{ expression = $jsA; awaitPromise = $true; returnByValue = $true }
$rA = Wait-Response $idA
$resultA = $rA.result.result.value
Write-Output ("PHASE A: " + ($resultA | ConvertTo-Json -Depth 6 -Compress))
if (-not $resultA.ok) { Send-Cdp 'Page.stopScreencast' @{} | Out-Null; $ws.Dispose(); throw 'phase A failed' }

# ---------- trusted legend toggles: Source Trajectory off -> on ----------
$tx = [double]$resultA.toggleX; $ty = [double]$resultA.toggleY
Trusted-Click $tx $ty
Pump; Pump; Start-Sleep -Milliseconds 900
Trusted-Click $tx $ty
Pump; Pump; Start-Sleep -Milliseconds 700

# ---------- phase B ----------
$jsB = '(async () => {' + (Get-Content $PhaseB -Raw) + '})()'
$idB = Send-Cdp 'Runtime.evaluate' @{ expression = $jsB; awaitPromise = $true; returnByValue = $true }
$rB = Wait-Response $idB
$resultB = $rB.result.result.value
Write-Output ("PHASE B: " + ($resultB | ConvertTo-Json -Depth 6 -Compress))

# ---------- stop ----------
Send-Cdp 'Page.stopScreencast' @{} | Out-Null
$stopId = Send-Cdp 'Runtime.evaluate' @{ expression = '1+1'; returnByValue = $true }
Wait-Response $stopId | Out-Null
$ws.Dispose()

# ---------- concat list ----------
$listPath = Join-Path $OutDir 'list.txt'
$lines = New-Object System.Collections.Generic.List[string]
$lines.Add("ffconcat version 1.0")
for ($i = 0; $i -lt $frames.Count; $i++) {
    $f = $frames[$i]
    $d = $f.dur; if ($d -lt 0.08) { $d = 0.08 }
    if ($d -gt 4) { $d = 4 }   # compress long idle gaps (spinner, forward projection)
    $lines.Add("file 'frame_{0:d4}.jpg'" -f ($i + 1))
    $lines.Add("duration {0:0.000}" -f $d)
}
$lines.Add("file 'frame_{0:d4}.jpg'" -f $frames.Count)
[IO.File]::WriteAllLines($listPath, $lines)
Write-Output ("FRAMES: " + $frames.Count + "  -> " + $listPath)

