const center = el => { const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; };

// find the ancestor that actually scrolls (Streamlit nests its own scroll container)
const scrollHost = el => {
  let n = el;
  while (n && n !== document.body) {
    const s = getComputedStyle(n);
    if (/(auto|scroll)/.test(s.overflowY) && n.scrollHeight > n.clientHeight + 10) return n;
    n = n.parentElement;
  }
  return document.scrollingElement || document.documentElement;
};
// step-scroll an element into view so the motion is visible in the frames
async function scrollIntoViewSlow(el, ms) {
  ms = ms || 700;
  const host = scrollHost(el);
  const rect = el.getBoundingClientRect();
  const isWindow = host === document.scrollingElement || host === document.documentElement;
  const startTop = isWindow ? (window.pageYOffset || 0) : host.scrollTop;
  const targetTop = Math.max(0, startTop + rect.top - 90);   // leave some headroom above the element
  const delta = targetTop - startTop;
  if (Math.abs(delta) < 10) return;
  const steps = Math.max(6, Math.round(ms / 90));
  for (let i = 1; i <= steps; i++) {
    const v = startTop + delta * i / steps;
    if (isWindow) window.scrollTo(0, v); else host.scrollTop = v;
    await sleep(90);
  }
}
// move the overlay cursor down the page while the view scrolls (visible scroll gesture)
async function scrollWithCursor(el, ms) {
  const c0 = center(el);
  await glide(c0.x, Math.max(140, c0.y * 0.5), 400);   // cursor toward middle/bottom edge
  const steps = Math.max(6, Math.round((ms || 700) / 90));
  for (let i = 0; i < steps; i++) {
    const r = el.getBoundingClientRect();
    const host = scrollHost(el);
    const isWindow = host === document.scrollingElement || host === document.documentElement;
    const step = Math.max(24, Math.abs(r.top - 90) / (steps - i));
    if (isWindow) window.scrollBy(0, r.top > 90 ? step : -step); else host.scrollTop += r.top > 90 ? step : -step;
    cur.style.top = Math.min(window.innerHeight - 60, parseFloat(cur.style.top) + 30) + 'px';
    await sleep(90);
  }
}

const btn = sub => q('button').find(b => b.innerText.includes(sub) && visible(b));

